fn init_test_tracing() {
    static INIT: std::sync::Once = std::sync::Once::new();
    INIT.call_once(|| {
        let _ = tracing_subscriber::fmt()
            .with_env_filter(tracing_subscriber::EnvFilter::from_default_env())
            .try_init();
    });
}

static TEST_ENV_LOCK: std::sync::OnceLock<tokio::sync::Mutex<()>> = std::sync::OnceLock::new();
static PRECOMPUTE_DELAY_ENV_LOCK: std::sync::OnceLock<tokio::sync::Mutex<()>> =
    std::sync::OnceLock::new();

async fn lock_test_env() -> tokio::sync::MutexGuard<'static, ()> {
    TEST_ENV_LOCK
        .get_or_init(|| tokio::sync::Mutex::new(()))
        .lock()
        .await
}

fn lock_test_env_blocking() -> tokio::sync::MutexGuard<'static, ()> {
    TEST_ENV_LOCK
        .get_or_init(|| tokio::sync::Mutex::new(()))
        .blocking_lock()
}

async fn lock_test_env_mutex(
    mutex: &'static std::sync::OnceLock<tokio::sync::Mutex<()>>,
) -> tokio::sync::MutexGuard<'static, ()> {
    mutex
        .get_or_init(|| tokio::sync::Mutex::new(()))
        .lock()
        .await
}

fn parse_backend_tree_for_test(text: &str) -> Arc<Tree> {
    let mut parser = TreeSitterParser::new();
    parser
        .set_language(&tree_sitter_bsl::LANGUAGE.into())
        .expect("tree-sitter-bsl language");
    Arc::new(
        parser
            .parse(text, None)
            .expect("tree-sitter parse for snapshot"),
    )
}

fn parse_snapshot_for_test(
    file_id: bsl_analysis_v2::FileId,
    file_version: i32,
    text: &str,
    changed_ranges: Vec<ParseChangedRange>,
    incremental: bool,
    fallback_reason: Option<&str>,
) -> ParseSnapshot {
    ParseSnapshot {
        file_id,
        file_version,
        parse_result: Arc::new(
            bsl_syntax::parse(text, &ParseOptions::default()).expect("snapshot parse"),
        ),
        line_index: Arc::new(LineIndex::new(text)),
        backend_tree: parse_backend_tree_for_test(text),
        changed_ranges: Arc::new(changed_ranges),
        produced_at_millis: 0,
        backend_tree_hash: 0,
        incremental,
        fallback_reason: fallback_reason.map(Arc::from),
    }
}

